/* Compact AVX2 SHA-256, 4-way interleaved, based on public-domain style
   implementation ideas (Intel SHA256 multi-buffer). Single-buffer version
   processes 1 block at a time with AVX2 message schedule (not 4-way) first
   as a baseline, then we'll do 4 independent if needed. */

#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <immintrin.h>
#include <mach/mach_time.h>
#include <CommonCrypto/CommonDigest.h>

static const uint32_t K[64] = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

static inline uint32_t rotr(uint32_t x, int n) { return (x >> n) | (x << (32 - n)); }

static inline uint32_t bswap32(uint32_t x) {
    return __builtin_bswap32(x);
}

/* scalar reference for correctness */
static void sha256_block_scalar(uint32_t state[8], const uint8_t block[64]) {
    uint32_t w[64];
    for (int i = 0; i < 16; i++) {
        uint32_t v;
        memcpy(&v, block + 4*i, 4);
        w[i] = bswap32(v);
    }
    for (int i = 16; i < 64; i++) {
        uint32_t s0 = rotr(w[i-15], 7) ^ rotr(w[i-15], 18) ^ (w[i-15] >> 3);
        uint32_t s1 = rotr(w[i-2], 17) ^ rotr(w[i-2], 19) ^ (w[i-2] >> 10);
        w[i] = w[i-16] + s0 + w[i-7] + s1;
    }
    uint32_t a=state[0],b=state[1],c=state[2],d=state[3],e=state[4],f=state[5],g=state[6],h=state[7];
    for (int i = 0; i < 64; i++) {
        uint32_t S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
        uint32_t ch = (e & f) ^ (~e & g);
        uint32_t t1 = h + S1 + ch + K[i] + w[i];
        uint32_t S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
        uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
        uint32_t t2 = S0 + maj;
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    state[0]+=a; state[1]+=b; state[2]+=c; state[3]+=d;
    state[4]+=e; state[5]+=f; state[6]+=g; state[7]+=h;
}

/* AVX2 message schedule for one block, scalar compression.
   Goal: see if schedule is the bottleneck. */
static void sha256_block_avx2sched(uint32_t state[8], const uint8_t block[64]) {
    __m128i bswap_mask = _mm_set_epi8(12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3);
    __m128i w0 = _mm_loadu_si128((const __m128i*)(block));
    __m128i w1 = _mm_loadu_si128((const __m128i*)(block+16));
    __m128i w2 = _mm_loadu_si128((const __m128i*)(block+32));
    __m128i w3 = _mm_loadu_si128((const __m128i*)(block+48));
    w0 = _mm_shuffle_epi8(w0, bswap_mask);
    w1 = _mm_shuffle_epi8(w1, bswap_mask);
    w2 = _mm_shuffle_epi8(w2, bswap_mask);
    w3 = _mm_shuffle_epi8(w3, bswap_mask);

    uint32_t w[64];
    _mm_storeu_si128((__m128i*)(w+0), w0);
    _mm_storeu_si128((__m128i*)(w+4), w1);
    _mm_storeu_si128((__m128i*)(w+8), w2);
    _mm_storeu_si128((__m128i*)(w+12), w3);

    /* expand with AVX2: compute 4 words at a time using the standard
       s0/s1 formulation. For i=16..63, w[i] depends on w[i-2] so a naive
       4-wide schedule needs a careful formulation. We'll do scalar expand
       here just to compare compression vs load. Actually let's do scalar expand
       to isolate compression cost. */
    for (int i = 16; i < 64; i++) {
        uint32_t s0 = rotr(w[i-15], 7) ^ rotr(w[i-15], 18) ^ (w[i-15] >> 3);
        uint32_t s1 = rotr(w[i-2], 17) ^ rotr(w[i-2], 19) ^ (w[i-2] >> 10);
        w[i] = w[i-16] + s0 + w[i-7] + s1;
    }
    uint32_t a=state[0],b=state[1],c=state[2],d=state[3],e=state[4],f=state[5],g=state[6],h=state[7];
    for (int i = 0; i < 64; i++) {
        uint32_t S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
        uint32_t ch = (e & f) ^ (~e & g);
        uint32_t t1 = h + S1 + ch + K[i] + w[i];
        uint32_t S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
        uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
        uint32_t t2 = S0 + maj;
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    state[0]+=a; state[1]+=b; state[2]+=c; state[3]+=d;
    state[4]+=e; state[5]+=f; state[6]+=g; state[7]+=h;
}

static void sha256_scalar(const uint8_t *data, size_t len, uint8_t out[32]) {
    uint32_t state[8] = {
        0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
        0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19
    };
    size_t nblocks = len / 64;
    for (size_t i = 0; i < nblocks; i++) sha256_block_scalar(state, data + i*64);
    /* padding */
    uint8_t block[128];
    size_t rem = len % 64;
    memcpy(block, data + nblocks*64, rem);
    block[rem] = 0x80;
    size_t pad_len = (rem < 56) ? 64 : 128;
    memset(block + rem + 1, 0, pad_len - rem - 1 - 8);
    uint64_t bits = (uint64_t)len * 8;
    for (int i = 0; i < 8; i++) block[pad_len - 1 - i] = (uint8_t)(bits >> (8*i));
    sha256_block_scalar(state, block);
    if (pad_len == 128) sha256_block_scalar(state, block+64);
    for (int i = 0; i < 8; i++) {
        uint32_t v = bswap32(state[i]);
        memcpy(out + 4*i, &v, 4);
    }
}

static double now_s(void) {
    static mach_timebase_info_data_t tb = {0};
    if (!tb.denom) mach_timebase_info(&tb);
    return (double)mach_absolute_time() * tb.numer / tb.denom / 1e9;
}

int main() {
    size_t n = 20000ull * 1024;
    uint8_t *data = malloc(n);
    memset(data, 0x5a, n);
    uint8_t md1[32], md2[32];
    sha256_scalar(data, n, md1);
    CC_SHA256(data, (CC_LONG)n, md2);
    printf("match %d\n", memcmp(md1, md2, 32)==0);
    if (memcmp(md1, md2, 32)) {
        for (int i=0;i<32;i++) printf("%02x", md1[i]); printf("\n");
        for (int i=0;i<32;i++) printf("%02x", md2[i]); printf("\n");
    }
    double t0 = now_s();
    for (int i = 0; i < 3; i++) sha256_scalar(data, n, md1);
    double t1 = now_s();
    printf("scalar %.2f ms  %.1f MB/s\n", (t1-t0)/3*1000, (3.0*n/1e6)/(t1-t0));
    t0 = now_s();
    for (int i = 0; i < 3; i++) CC_SHA256(data, (CC_LONG)n, md2);
    t1 = now_s();
    printf("CC     %.2f ms  %.1f MB/s\n", (t1-t0)/3*1000, (3.0*n/1e6)/(t1-t0));
    return 0;
}
EOF
