clang -O3 -mavx2 -mbmi2 -isysroot "$SDK" -o sha256_avx2 sha256_avx2.c && ./sha256_avx2"}

{"command":"cd "$HOME/sha_bench" && cat > sha4.c << 'EOF'
/* 4-way interleaved SHA-256 using AVX2 (4x uint32 in xmm/ymm lanes conceptually
   via 128-bit SSE for 4 words). Processes 4 independent 64-byte blocks in
   parallel — but SHA-256 is chained, so this only helps if we hash 4 independent
   messages. For a single message this does NOT compute the correct digest.
   This is a throughput probe only. */
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <immintrin.h>
#include <mach/mach_time.h>
#include <CommonCrypto/CommonDigest.h>

static const uint32_t K[64] = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

/* 4 independent messages, each of length len (multiple of 64, no padding here — raw blocks).
   Returns nothing useful; measures compression throughput. */
static void sha256_x4_blocks(const uint8_t *m0, const uint8_t *m1, const uint8_t *m2, const uint8_t *m3, size_t nblocks, uint32_t out[4][8]) {
    __m128i a = _mm_set1_epi32(0x6a09e667);
    __m128i b = _mm_set1_epi32(0xbb67ae85);
    __m128i c = _mm_set1_epi32(0x3c6ef372);
    __m128i d = _mm_set1_epi32(0xa54ff53a);
    __m128i e = _mm_set1_epi32(0x510e527f);
    __m128i f = _mm_set1_epi32(0x9b05688c);
    __m128i g = _mm_set1_epi32(0x1f83d9ab);
    __m128i h = _mm_set1_epi32(0x5be0cd19);

    const __m128i *p0 = (const __m128i*)m0;
    const __m128i *p1 = (const __m128i*)m1;
    const __m128i *p2 = (const __m128i*)m2;
    const __m128i *p3 = (const __m128i*)m3;

    __m128i bswap = _mm_set_epi8(12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3);

    for (size_t blk = 0; blk < nblocks; blk++) {
        __m128i W[64];
        /* load 16 words, transpose 4 messages into lanes.
           Each message block is 4 x __m128i (16 words). */
        __m128i r0[4], r1[4], r2[4], r3[4];
        for (int i = 0; i < 4; i++) {
            r0[i] = _mm_shuffle_epi8(_mm_loadu_si128(p0 + blk*4 + i), bswap);
            r1[i] = _mm_shuffle_epi8(_mm_loadu_si128(p1 + blk*4 + i), bswap);
            r2[i] = _mm_shuffle_epi8(_mm_loadu_si128(p2 + blk*4 + i), bswap);
            r3[i] = _mm_shuffle_epi8(_mm_loadu_si128(p3 + blk*4 + i), bswap);
        }
        /* transpose 4x4 words: rX[i] holds words 4i..4i+3 of message X.
           We want W[4i+j] = words of all 4 messages. */
        for (int i = 0; i < 4; i++) {
            /* r0[i], r1[i], r2[i], r3[i] each have 4 words */
            __m128i t0 = _mm_unpacklo_epi32(r0[i], r1[i]);
            __m128i t1 = _mm_unpackhi_epi32(r0[i], r1[i]);
            __m128i t2 = _mm_unpacklo_epi32(r2[i], r3[i]);
            __m128i t3 = _mm_unpackhi_epi32(r2[i], r3[i]);
            W[4*i+0] = _mm_unpacklo_epi64(t0, t2);
            W[4*i+1] = _mm_unpackhi_epi64(t0, t2);
            W[4*i+2] = _mm_unpacklo_epi64(t1, t3);
            W[4*i+3] = _mm_unpackhi_epi64(t1, t3);
        }
        for (int i = 16; i < 64; i++) {
            /* s0 = rotr7 ^ rotr18 ^ shr3 */
            __m128i x = W[i-15];
            __m128i s0 = _mm_xor_si128(_mm_xor_si128(_mm_ror_epi32(x, 7), _mm_ror_epi32(x, 18)), _mm_srli_epi32(x, 3));
            x = W[i-2];
            __m128i s1 = _mm_xor_si128(_mm_xor_si128(_mm_ror_epi32(x, 17), _mm_ror_epi32(x, 19)), _mm_srli_epi32(x, 10));
            W[i] = _mm_add_epi32(_mm_add_epi32(W[i-16], s0), _mm_add_epi32(W[i-7], s1));
        }
        __m128i aa=a, bb=b, cc=c, dd=d, ee=e, ff=f, gg=g, hh=h;
        for (int i = 0; i < 64; i++) {
            __m128i S1 = _mm_xor_si128(_mm_xor_si128(_mm_ror_epi32(ee, 6), _mm_ror_epi32(ee, 11)), _mm_ror_epi32(ee, 25));
