            hh=gg; gg=ff; ff=ee; ee=_mm_add_epi32(dd, t1); dd=cc; cc=bb; bb=aa; aa=_mm_add_epi32(t1, t2);
        }
        a=_mm_add_epi32(a, aa);
        b=_mm_add_epi32(b, bb);
        c=_mm_add_epi32(c, cc);
        d=_mm_add_epi32(d, dd);
        e=_mm_add_epi32(e, ee);
        f=_mm_add_epi32(f, ff);
        g=_mm_add_epi32(g, gg);
        h=_mm_add_epi32(h, hh);
