    uint32_t tmp[4];
    _mm_storeu_si128((__m128i*)tmp, a); out[0][0]=tmp[0]; out[1][0]=tmp[1]; out[2][0]=tmp[2]; out[3][0]=tmp[3];
    _mm_storeu_si128((__m128i*)tmp, b); out[0][1]=tmp[0];
    _mm_storeu_si128((__m128i*)tmp, c); out[0][2]=tmp[0];
    _mm_storeu_si128((__m128i*)tmp, d); out[0][3]=tmp[0];
    _mm_storeu_si128((__m128i*)tmp, e); out[0][4]=tmp[0];
