/* 8 independent messages, raw blocks, no padding. Throughput probe. */
static void sha256_x8(const uint8_t *msg[8], size_t nblocks) {
    __m256i a = _mm256_set1_epi32(0x6a09e667);
    __m256i b = _mm256_set1_epi32(0xbb67ae85);
    __m256i c = _mm256_set1_epi32(0x3c6ef372);
    __m256i d = _mm256_set1_epi32(0xa54ff53a);
    __m256i e = _mm256_set1_epi32(0x510e527f);
    __m256i f = _mm256_set1_epi32(0x9b05688c);
    __m256i g = _mm256_set1_epi32(0x1f83d9ab);
    __m256i h = _mm256_set1_epi32(0x5be0cd19);
    __m128i bswap = _mm_set_epi8(12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3);

    for (size_t blk = 0; blk < nblocks; blk++) {
        __m256i W[64];
        __m128i rows[8][4];
        for (int m = 0; m < 8; m++) {
            const __m128i *p = (const __m128i*)(msg[m] + blk*64);
            for (int i = 0; i < 4; i++)
                rows[m][i] = _mm_shuffle_epi8(_mm_loadu_si128(p + i), bswap);
        }
        /* For each group of 4 words, transpose 8 messages.
           Simpler: build W by extracting word-by-word — slower but OK for probe?
           Let's do proper transpose per 4-word group into two ymm via two 4-msg transposes. */
        for (int i = 0; i < 4; i++) {
            /* low 4 messages */
            __m128i t0 = _mm_unpacklo_epi32(rows[0][i], rows[1][i]);
            __m128i t1 = _mm_unpackhi_epi32(rows[0][i], rows[1][i]);
            __m128i t2 = _mm_unpacklo_epi32(rows[2][i], rows[3][i]);
            __m128i t3 = _mm_unpackhi_epi32(rows[2][i], rows[3][i]);
            __m128i lo0 = _mm_unpacklo_epi64(t0, t2);
            __m128i lo1 = _mm_unpackhi_epi64(t0, t2);
            __m128i lo2 = _mm_unpacklo_epi64(t1, t3);
            __m128i lo3 = _mm_unpackhi_epi64(t1, t3);
            t0 = _mm_unpacklo_epi32(rows[4][i], rows[5][i]);
            t1 = _mm_unpackhi_epi32(rows[4][i], rows[5][i]);
            t2 = _mm_unpacklo_epi32(rows[6][i], rows[7][i]);
            t3 = _mm_unpackhi_epi32(rows[6][i], rows[7][i]);
            __m128i hi0 = _mm_unpacklo_epi64(t0, t2);
            __m128i hi1 = _mm_unpackhi_epi64(t0, t2);
            __m128i hi2 = _mm_unpacklo_epi64(t1, t3);
            __m128i hi3 = _mm_unpackhi_epi64(t1, t3);
            W[4*i+0] = _mm256_set_m128i(hi0, lo0);
            W[4*i+1] = _mm256_set_m128i(hi1, lo1);
            W[4*i+2] = _mm256_set_m128i(hi2, lo2);
            W[4*i+3] = _mm256_set_m128i(hi3, lo3);
        }
        for (int i = 16; i < 64; i++) {
            __m256i x = W[i-15];
            __m256i s0 = _mm256_xor_si256(_mm256_xor_si256(ror32(x, 7), ror32(x, 18)), _mm256_srli_epi32(x, 3));
            x = W[i-2];
            __m256i s1 = _mm256_xor_si256(_mm256_xor_si256(ror32(x, 17), ror32(x, 19)), _mm256_srli_epi32(x, 10));
            W[i] = _mm256_add_epi32(_mm256_add_epi32(W[i-16], s0), _mm256_add_epi32(W[i-7], s1));
        }
        __m256i aa=a,bb=b,cc=c,dd=d,ee=e,ff=f,gg=g,hh=h;
        for (int i = 0; i < 64; i++) {
            __m256i S1 = _mm256_xor_si256(_mm256_xor_si256(ror32(ee,6), ror32(ee,11)), ror32(ee,25));
            __m256i ch = _mm256_xor_si256(_mm256_and_si256(ee, ff), _mm256_andnot_si256(ee, gg));
            __m256i t1 = _mm256_add_epi32(hh, _mm256_add_epi32(S1, _mm256_add_epi32(ch, _mm256_add_epi32(_mm256_set1_epi32(K[i]), W[i]))));
            __m256i S0 = _mm256_xor_si256(_mm256_xor_si256(ror32(aa,2), ror32(aa,13)), ror32(aa,22));
            __m256i maj = _mm256_xor_si256(_mm256_xor_si256(_mm256_and_si256(aa, bb), _mm256_and_si256(aa, cc)), _mm256_and_si256(bb, cc));
            __m256i t2 = _mm256_add_epi32(S0, maj);
            hh=gg; gg=ff; ff=ee; ee=_mm256_add_epi32(dd, t1); dd=cc; cc=bb; bb=aa; aa=_mm256_add_epi32(t1, t2);
        }
        a=_mm256_add_epi32(a,aa); b=_mm256_add_epi32(b,bb); c=_mm256_add_epi32(c,cc); d=_mm256_add_epi32(d,dd);
        e=_mm256_add_epi32(e,ee); f=_mm256_add_epi32(f,ff); g=_mm256_add_epi32(g,gg); h=_mm256_add_epi32(h,hh);
