/* 2-level SHA-256 Merkle tree vs single SHA-256 throughput.
   Level 1: 8-way AVX2 hash of independent chunks (with proper padding).
   Level 2: scalar hash of concatenation of digests.
   Compare wall time to CC_SHA256 of the whole buffer. */
#include <stdio.h>
