#include <stdlib.h>
#include <string.h>
#include <immintrin.h>
#include <mach/mach_time.h>
#include <CommonCrypto/CommonDigest.h>

static inline __m256i ror32(__m256i x, int n) {
    return _mm256_or_si256(_mm256_srli_epi32(x, n), _mm256_slli_epi32(x, 32-n));
}
static const uint32_t K[64] = {
