    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

/* Hash 8 messages of identical length `len` (arbitrary), produce 8 digests. */
static void sha256_x8_full(const uint8_t *msg[8], size_t len, uint8_t digests[8][32]) {
    __m256i a = _mm256_set1_epi32(0x6a09e667);
    __m256i b = _mm256_set1_epi32(0xbb67ae85);
    __m256i c = _mm256_set1_epi32(0x3c6ef372);
    __m256i d = _mm256_set1_epi32(0xa54ff53a);
    __m256i e = _mm256_set1_epi32(0x510e527f);
    __m256i f = _mm256_set1_epi32(0x9b05688c);
    __m256i g = _mm256_set1_epi32(0x1f83d9ab);
    __m256i h = _mm256_set1_epi32(0x5be0cd19);
    __m128i bswap = _mm_set_epi8(12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3);

    size_t nfull = len / 64;

    #define ROUND_BLOCK(load_word) do { \
        __m256i W[64]; \
        for (int i = 0; i < 16; i++) { \
            uint32_t words[8]; \
            for (int m = 0; m < 8; m++) words[m] = load_word(m, i); \
            W[i] = _mm256_loadu_si256((const __m256i*)words); \
        } \
        for (int i = 16; i < 64; i++) { \
            __m256i x = W[i-15]; \
            __m256i s0 = _mm256_xor_si256(_mm256_xor_si256(ror32(x,7), ror32(x,18)), _mm256_srli_epi32(x,3)); \
            x = W[i-2]; \
            __m256i s1 = _mm256_xor_si256(_mm256_xor_si256(ror32(x,17), ror32(x,19)), _mm256_srli_epi32(x,10)); \
            W[i] = _mm256_add_epi32(_mm256_add_epi32(W[i-16], s0), _mm256_add_epi32(W[i-7], s1)); \
        } \
        __m256i aa=a,bb=b,cc=c,dd=d,ee=e,ff=f,gg=g,hh=h; \
        for (int i = 0; i < 64; i++) { \
            __m256i S1 = _mm256_xor_si256(_mm256_xor_si256(ror32(ee,6), ror32(ee,11)), ror32(ee,25)); \
            __m256i ch = _mm256_xor_si256(_mm256_and_si256(ee, ff), _mm256_andnot_si256(ee, gg)); \
            __m256i t1 = _mm256_add_epi32(hh, _mm256_add_epi32(S1, _mm256_add_epi32(ch, _mm256_add_epi32(_mm256_set1_epi32(K[i]), W[i])))); \
            __m256i S0 = _mm256_xor_si256(_mm256_xor_si256(ror32(aa,2), ror32(aa,13)), ror32(aa,22)); \
            __m256i maj = _mm256_xor_si256(_mm256_xor_si256(_mm256_and_si256(aa, bb), _mm256_and_si256(aa, cc)), _mm256_and_si256(bb, cc)); \
            __m256i t2 = _mm256_add_epi32(S0, maj); \
            hh=gg; gg=ff; ff=ee; ee=_mm256_add_epi32(dd, t1); dd=cc; cc=bb; bb=aa; aa=_mm256_add_epi32(t1, t2); \
        } \
        a=_mm256_add_epi32(a,aa); b=_mm256_add_epi32(b,bb); c=_mm256_add_epi32(c,cc); d=_mm256_add_epi32(d,dd); \
        e=_mm256_add_epi32(e,ee); f=_mm256_add_epi32(f,ff); g=_mm256_add_epi32(g,gg); h=_mm256_add_epi32(h,hh); \
    } while (0)

    for (size_t blk = 0; blk < nfull; blk++) {
        #define LOAD_FULL(m, i) ({ \
            uint32_t v; memcpy(&v, msg[m] + blk*64 + 4*(i), 4); __builtin_bswap32(v); })
        ROUND_BLOCK(LOAD_FULL);
        #undef LOAD_FULL
    }
    /* padding block(s) */
    uint8_t pads[8][128];
    size_t rem = len % 64;
    size_t pad_len = (rem < 56) ? 64 : 128;
    uint64_t bits = (uint64_t)len * 8;
    for (int m = 0; m < 8; m++) {
        memset(pads[m], 0, pad_len);
        if (rem) memcpy(pads[m], msg[m] + nfull*64, rem);
        pads[m][rem] = 0x80;
        for (int i = 0; i < 8; i++) pads[m][pad_len - 1 - i] = (uint8_t)(bits >> (8*i));
    }
    size_t npad = pad_len / 64;
    for (size_t blk = 0; blk < npad; blk++) {
        #define LOAD_PAD(m, i) ({ \
            uint32_t v; memcpy(&v, pads[m] + blk*64 + 4*(i), 4); __builtin_bswap32(v); })
        ROUND_BLOCK(LOAD_PAD);
        #undef LOAD_PAD
    }
    #undef ROUND_BLOCK

    uint32_t A[8],B[8],C[8],D[8],E[8],F[8],G[8],H[8];
    _mm256_storeu_si256((__m256i*)A, a);
    _mm256_storeu_si256((__m256i*)B, b);
    _mm256_storeu_si256((__m256i*)C, c);
    _mm256_storeu_si256((__m256i*)D, d);
    _mm256_storeu_si256((__m256i*)E, e);
    _mm256_storeu_si256((__m256i*)F, f);
    _mm256_storeu_si256((__m256i*)G, g);
    _mm256_storeu_si256((__m256i*)H, h);
    for (int m = 0; m < 8; m++) {
        uint32_t st[8] = {A[m],B[m],C[m],D[m],E[m],F[m],G[m],H[m]};
        for (int i = 0; i < 8; i++) {
            uint32_t v = __builtin_bswap32(st[i]);
            memcpy(digests[m] + 4*i, &v, 4);
        }
    }
}

static double now_s(void) {
    static mach_timebase_info_data_t tb = {0};
    if (!tb.denom) mach_timebase_info(&tb);
    return (double)mach_absolute_time() * tb.numer / tb.denom / 1e9;
}

int main() {
    size_t total = 20000ull * 1024;
    size_t chunk = total / 8;
    uint8_t *data = malloc(total);
    memset(data, 0x5a, total);
    const uint8_t *msg[8];
    for (int i = 0; i < 8; i++) msg[i] = data + i*chunk;
    uint8_t digests[8][32];

    /* correctness vs CC */
    sha256_x8_full(msg, chunk, digests);
    int ok = 1;
    for (int i = 0; i < 8; i++) {
