/* msg[m] must be 64-byte aligned, length multiple of 64. No padding (caller pads). */
static void sha256_x8_blocks(const uint8_t *msg[8], size_t nblocks,
                             __m256i *oa, __m256i *ob, __m256i *oc, __m256i *od,
                             __m256i *oe, __m256i *of, __m256i *og, __m256i *oh) {
    __m256i a = _mm256_set1_epi32(0x6a09e667);
    __m256i b = _mm256_set1_epi32(0xbb67ae85);
    __m256i c = _mm256_set1_epi32(0x3c6ef372);
    __m256i d = _mm256_set1_epi32(0xa54ff53a);
    __m256i e = _mm256_set1_epi32(0x510e527f);
    __m256i f = _mm256_set1_epi32(0x9b05688c);
    __m256i g = _mm256_set1_epi32(0x1f83d9ab);
    __m256i h = _mm256_set1_epi32(0x5be0cd19);

    /* byte-swap within each 32-bit word, for a 256-bit load of 8 words of ONE message.
       We'll load 32 bytes (8 words) per message then transpose 8x8. */
    const __m256i bswap32_mask = _mm256_set_epi8(
        12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3,
        12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3);

    for (size_t blk = 0; blk < nblocks; blk++) {
        __m256i W[64];
        /* Each block is 64 bytes = 2 x 32-byte chunks of 8 words.
           Load 8 messages x 8 words, transpose to 8 W vectors, twice. */
        for (int half = 0; half < 2; half++) {
            __m256i r[8];
            for (int m = 0; m < 8; m++) {
                r[m] = _mm256_loadu_si256((const __m256i*)(msg[m] + blk*64 + half*32));
                r[m] = _mm256_shuffle_epi8(r[m], bswap32_mask);
            }
            /* 8x8 transpose of 32-bit lanes.
               r[m] lane k = word (half*8+k) of message m.
               Want W[half*8+k] lane m = word of message m. */
            /* First, interleave 32-bit pairs */
            __m256i t0 = _mm256_unpacklo_epi32(r[0], r[1]);
            __m256i t1 = _mm256_unpackhi_epi32(r[0], r[1]);
            __m256i t2 = _mm256_unpacklo_epi32(r[2], r[3]);
            __m256i t3 = _mm256_unpackhi_epi32(r[2], r[3]);
            __m256i t4 = _mm256_unpacklo_epi32(r[4], r[5]);
            __m256i t5 = _mm256_unpackhi_epi32(r[4], r[5]);
            __m256i t6 = _mm256_unpacklo_epi32(r[6], r[7]);
            __m256i t7 = _mm256_unpackhi_epi32(r[6], r[7]);
