            __m256i u0 = _mm256_unpacklo_epi64(t0, t2);
            __m256i u1 = _mm256_unpackhi_epi64(t0, t2);
            __m256i u2 = _mm256_unpacklo_epi64(t1, t3);
            __m256i u3 = _mm256_unpackhi_epi64(t1, t3);
            __m256i u4 = _mm256_unpacklo_epi64(t4, t6);
            __m256i u5 = _mm256_unpackhi_epi64(t4, t6);
            __m256i u6 = _mm256_unpacklo_epi64(t5, t7);
            __m256i u7 = _mm256_unpackhi_epi64(t5, t7);
            /* 128-bit interleave via permute2x128 */
            W[half*8+0] = _mm256_permute2x128_si256(u0, u4, 0x20);
            W[half*8+4] = _mm256_permute2x128_si256(u0, u4, 0x31);
            W[half*8+1] = _mm256_permute2x128_si256(u1, u5, 0x20);
            W[half*8+5] = _mm256_permute2x128_si256(u1, u5, 0x31);
            W[half*8+2] = _mm256_permute2x128_si256(u2, u6, 0x20);
            W[half*8+6] = _mm256_permute2x128_si256(u2, u6, 0x31);
            W[half*8+3] = _mm256_permute2x128_si256(u3, u7, 0x20);
            W[half*8+7] = _mm256_permute2x128_si256(u3, u7, 0x31);
        }
        for (int i = 16; i < 64; i++) {
            __m256i x = W[i-15];
            __m256i s0 = _mm256_xor_si256(_mm256_xor_si256(ror32(x,7), ror32(x,18)), _mm256_srli_epi32(x,3));
            x = W[i-2];
            __m256i s1 = _mm256_xor_si256(_mm256_xor_si256(ror32(x,17), ror32(x,19)), _mm256_srli_epi32(x,10));
            W[i] = _mm256_add_epi32(_mm256_add_epi32(W[i-16], s0), _mm256_add_epi32(W[i-7], s1));
        }
        __m256i aa=a,bb=b,cc=c,dd=d,ee=e,ff=f,gg=g,hh=h;
        #pragma unroll 8
        for (int i = 0; i < 64; i++) {
            __m256i S1 = _mm256_xor_si256(_mm256_xor_si256(ror32(ee,6), ror32(ee,11)), ror32(ee,25));
            __m256i ch = _mm256_xor_si256(_mm256_and_si256(ee, ff), _mm256_andnot_si256(ee, gg));
            __m256i t1 = _mm256_add_epi32(hh, _mm256_add_epi32(S1, _mm256_add_epi32(ch, _mm256_add_epi32(_mm256_set1_epi32(K[i]), W[i]))));
