            __m256i maj = _mm256_xor_si256(_mm256_xor_si256(_mm256_and_si256(aa, bb), _mm256_and_si256(aa, cc)), _mm256_and_si256(bb, cc));
            __m256i t2 = _mm256_add_epi32(S0, maj);
            hh=gg; gg=ff; ff=ee; ee=_mm256_add_epi32(dd, t1); dd=cc; cc=bb; bb=aa; aa=_mm256_add_epi32(t1, t2);
