    __m256i a,b,c,d,e,f,g,h;
    /* We'll build padded buffers only for the tail, and if nfull==0 handle all via pad. */
    if (nfull) {
        sha256_x8_blocks(src, nfull, &a,&b,&c,&d,&e,&f,&g,&h);
    } else {
        a = _mm256_set1_epi32(0x6a09e667);
        b = _mm256_set1_epi32(0xbb67ae85);
        c = _mm256_set1_epi32(0x3c6ef372);
        d = _mm256_set1_epi32(0xa54ff53a);
        e = _mm256_set1_epi32(0x510e527f);
        f = _mm256_set1_epi32(0x9b05688c);
        g = _mm256_set1_epi32(0x1f83d9ab);
        h = _mm256_set1_epi32(0x5be0cd19);
    }
    /* padding: 1 or 2 blocks. Feed as a fresh "message" of pad_len whose blocks continue state.
       Easiest: copy pad into 8 small buffers and call a state-continuing function.
       Inline by reusing sha256 but we need to continue state. Let's just manually call block loop
       by placing pads as msg and using a variant. For simplicity, construct 8 pad messages and
       run a tiny continuation. */
    size_t pad_len = (rem < 56) ? 64 : 128;
    uint8_t pads[8][128] __attribute__((aligned(32)));
    uint64_t bits = (uint64_t)len * 8;
    const uint8_t *pmsg[8];
    for (int m = 0; m < 8; m++) {
        memset(pads[m], 0, pad_len);
        if (rem) memcpy(pads[m], src[m] + nfull*64, rem);
        pads[m][rem] = 0x80;
        for (int i = 0; i < 8; i++) pads[m][pad_len-1-i] = (uint8_t)(bits >> (8*i));
        pmsg[m] = pads[m];
    }
    /* continue state: duplicate block function body is annoying. We'll save state, but
       sha256_x8_blocks resets IV. So do padding by appending to a copy only if nfull is small.
       For the benchmark, len is huge and multiple of 64? 20MB/8 = 2.5MB exactly? 20000*1024/8 = 2560000, not multiple of 64?
       2560000 / 64 = 40000 exactly. Yes 2560000 = 2.5*1024*1024 = 2621440? Wait:
       20000*1024 = 20,480,000. /8 = 2,560,000. 2560000/64 = 40000 exactly. rem=0.
       For rem=0, padding is a full extra block (0x80 + zeros + length), pad_len=64.
    */
    /* We need continuation. Implement by calling an internal that accepts initial state.
       Quick hack: since rem==0 in bench, still must be correct generally. Let's write continue inline
       by abusing a modified copy. I'll just re-run block function logic via function pointer style:
       export a version that takes initial state. */
    /* FALLBACK correctness path: not used if we fix below. */
    (void)a;(void)b;(void)c;(void)d;(void)e;(void)f;(void)g;(void)h;(void)pmsg;
    /* We'll replace this function; placeholder to compile-check transpose first on no-pad messages. */
    state_to_digests(a,b,c,d,e,f,g,h, digests);
}

static double now_s(void) {
    static mach_timebase_info_data_t tb = {0};
    if (!tb.denom) mach_timebase_info(&tb);
    return (double)mach_absolute_time() * tb.numer / tb.denom / 1e9;
}

int main() {
    size_t n = 2*1024*1024; /* multiple of 64, NO padding in this probe */
    uint8_t *buf[8];
    const uint8_t *msg[8];
    for (int i = 0; i < 8; i++) {
        buf[i] = aligned_alloc(64, n);
        memset(buf[i], 0x5a, n);
