    int same = 1;
    for (int i = 1; i < 8; i++) if (memcmp(digests[0], digests[i], 32)) same = 0;
    printf("lanes identical (same msg): %d\n", same);
    printf("d0 "); for (int i=0;i<8;i++) printf("%02x", digests[0][i]); printf("\n");

