    double t0 = now_s();
    for (int r = 0; r < reps; r++) sha256_x8_blocks(msg, n/64, &a,&b,&c,&d,&e,&f,&g,&h);
    double t1 = now_s();
    double bytes = (double)reps * 8 * n;
    printf("x8 blocks %.2f ms/rep  %.1f MB/s\n", (t1-t0)/reps*1000, (bytes/1e6)/(t1-t0));
    return 0;
}
