    uint32_t *W = aligned_alloc(64, NB * 64 * sizeof(uint32_t));
    for (int i = 0; i < NB*64; i++) W[i] = i*0x9e3779b9u;
    uint32_t st[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    /* warmup */
    for (int i = 0; i < NB; i++) compress(st, W + i*64);
    int reps = 200; /* 200*1024 blocks = 204800 blocks ~ 12.8MB equivalent */
    uint64_t c0 = rdtsc();
    for (int r = 0; r < reps; r++) {
        for (int i = 0; i < NB; i++) compress(st, W + i*64);
    }
    uint64_t c1 = rdtsc();
    double blocks = (double)reps * NB;
    double bytes = blocks * 64;
    double cyc = (double)(c1-c0);
    printf("compress cycles/byte %.2f  (sink %08x)\n", cyc/bytes, st[0]);
    printf("at 2.6GHz would be %.1f MB/s, 20MB in %.2f ms\n", 2.6e9/(cyc/bytes)/1e6, 20e6 * (cyc/bytes) / 2.6e9 * 1000);

    /* schedule only */
    uint8_t *blocks_b = aligned_alloc(64, NB * 64);
    memset(blocks_b, 0x5a, NB*64);
    uint32_t *Ws = aligned_alloc(64, NB * 64 * sizeof(uint32_t));
    c0 = rdtsc();
    for (int r = 0; r < reps; r++) {
        for (int b = 0; b < NB; b++) {
            uint32_t *w = Ws + b*64;
            const uint8_t *blk = blocks_b + b*64;
            for (int i = 0; i < 16; i++) {
                uint32_t v; memcpy(&v, blk+4*i, 4); w[i] = __builtin_bswap32(v);
            }
            for (int i = 16; i < 64; i++) {
                uint32_t s0 = rotr(w[i-15],7) ^ rotr(w[i-15],18) ^ (w[i-15]>>3);
                uint32_t s1 = rotr(w[i-2],17) ^ rotr(w[i-2],19) ^ (w[i-2]>>10);
                w[i] = w[i-16] + s0 + w[i-7] + s1;
            }
        }
    }
    c1 = rdtsc();
    cyc = (double)(c1-c0);
    printf("schedule cycles/byte %.2f (sink %08x)\n", cyc/bytes, Ws[0]);
    return 0;
}
EOF
