    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};
/* Only the e-chain, W and K pre-added, to estimate critical path floor. */
int main() {
    uint32_t w[64];
    for (int i = 0; i < 64; i++) w[i] = K[i] + i*0x1234567u;
    uint32_t a=0x6a09e667,b=0xbb67ae85,c=0x3c6ef372,d=0xa54ff53a,e=0x510e527f,f=0x9b05688c,g=0x1f83d9ab,h=0x5be0cd19;
    /* 20000*1024/64 = 320000 blocks */
    const int blocks = 320000;
    mach_timebase_info_data_t tb; mach_timebase_info(&tb);
    uint64_t t0 = mach_absolute_time();
    for (int blk = 0; blk < blocks; blk++) {
        uint32_t aa=a,bb=b,cc=c,dd=d,ee=e,ff=f,gg=g,hh=h;
        #pragma unroll 8
        for (int i = 0; i < 64; i++) {
            uint32_t S1 = rotr(ee,6) ^ rotr(ee,11) ^ rotr(ee,25);
            uint32_t ch = (ee & ff) ^ (~ee & gg);
            uint32_t t1 = hh + S1 + ch + w[i];
            uint32_t S0 = rotr(aa,2) ^ rotr(aa,13) ^ rotr(aa,22);
            uint32_t maj = (aa & bb) ^ (aa & cc) ^ (bb & cc);
            uint32_t t2 = S0 + maj;
            hh=gg; gg=ff; ff=ee; ee=dd+t1; dd=cc; cc=bb; bb=aa; aa=t1+t2;
        }
        a+=aa; b+=bb; c+=cc; d+=dd; e+=ee; f+=ff; g+=gg; h+=hh;
    }
    uint64_t t1 = mach_absolute_time();
    double ns = (double)(t1-t0) * tb.numer / tb.denom;
    double bytes = (double)blocks * 64;
    printf("compress-only %.2f ms for 20MB  %.1f MB/s  sink %08x\n", ns/1e6, (bytes/1e6)/(ns/1e9), a);
    printf("speedup vs 40ms reference would be %.2fx\n", 40.0 / (ns/1e6));
    return 0;
}
