{"command":"cd "$HOME/sha_bench" && cat > clsha.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <OpenCL/opencl.h>
#include <mach/mach_time.h>
#include <CommonCrypto/CommonDigest.h>

static const char *SRC =
"__constant uint K[64] = {\n"
"0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,\n"
"0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,\n"
"0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,\n"
"0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,\n"
"0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,\n"
"0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,\n"
"0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,\n"
"0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};\n"
"#define ROTR(x,n) rotate((uint)(x),(uint)(32-(n)))\n"
"/* each work-item hashes one independent chunk of nblocks 64-byte blocks, no padding (probe) */\n"
"__kernel void sha256_chunks(__global const uchar *data, __global uchar *out, uint nblocks) {\n"
"  uint id = get_global_id(0);\n"
"  uint a=0x6a09e667,b=0xbb67ae85,c=0x3c6ef372,d=0xa54ff53a,e=0x510e527f,f=0x9b05688c,g=0x1f83d9ab,h=0x5be0cd19;\n"
"  __global const uchar *p = data + (size_t)id * nblocks * 64;\n"
"  for (uint blk = 0; blk < nblocks; blk++) {\n"
"    uint w[64];\n"
"    for (int i = 0; i < 16; i++) {\n"
"      uint v = ((uint)p[0]<<24)|((uint)p[1]<<16)|((uint)p[2]<<8)|((uint)p[3]);\n"
"      w[i]=v; p+=4;\n"
"    }\n"
"    for (int i = 16; i < 64; i++) {\n"
"      uint s0 = ROTR(w[i-15],7) ^ ROTR(w[i-15],18) ^ (w[i-15]>>3);\n"
"      uint s1 = ROTR(w[i-2],17) ^ ROTR(w[i-2],19) ^ (w[i-2]>>10);\n"
"      w[i] = w[i-16] + s0 + w[i-7] + s1;\n"
"    }\n"
"    uint aa=a,bb=b,cc=c,dd=d,ee=e,ff=f,gg=g,hh=h;\n"
"    for (int i = 0; i < 64; i++) {\n"
"      uint S1 = ROTR(ee,6)^ROTR(ee,11)^ROTR(ee,25);\n"
"      uint ch = (ee & ff) ^ (~ee & gg);\n"
"      uint t1 = hh + S1 + ch + K[i] + w[i];\n"
"      uint S0 = ROTR(aa,2)^ROTR(aa,13)^ROTR(aa,22);\n"
"      uint maj = (aa & bb) ^ (aa & cc) ^ (bb & cc);\n"
"      uint t2 = S0 + maj;\n"
"      hh=gg; gg=ff; ff=ee; ee=dd+t1; dd=cc; cc=bb; bb=aa; aa=t1+t2;\n"
"    }\n"
"    a+=aa; b+=bb; c+=cc; d+=dd; e+=ee; f+=ff; g+=gg; h+=hh;\n"
"  }\n"
"  __global uchar *o = out + id*32;\n"
"  uint st[8]={a,b,c,d,e,f,g,h};\n"
"  for (int i = 0; i < 8; i++) {\n"
"    o[4*i]=st[i]>>24; o[4*i+1]=st[i]>>16; o[4*i+2]=st[i]>>8; o[4*i+3]=st[i];\n"
"  }\n"
"}\n";

static double now_s(void) {
    static mach_timebase_info_data_t tb={0};
    if (!tb.denom) mach_timebase_info(&tb);
    return (double)mach_absolute_time()*tb.numer/tb.denom/1e9;
}

static cl_device_id pick(const char *substr) {
    cl_platform_id plats[4]; cl_uint np=0;
    clGetPlatformIDs(4, plats, &np);
    cl_device_id devs[8]; cl_uint nd=0;
    clGetDeviceIDs(plats[0], CL_DEVICE_TYPE_ALL, 8, devs, &nd);
    for (cl_uint i = 0; i < nd; i++) {
        char name[256]={0};
        clGetDeviceInfo(devs[i], CL_DEVICE_NAME, sizeof name, name, NULL);
        if (strstr(name, substr)) return devs[i];
    }
    return NULL;
}

int main(int argc, char **argv) {
    const char *which = argc>1 ? argv[1] : "AMD";
    cl_device_id dev = pick(which);
    if (!dev) { printf("no device %s\n", which); return 1; }
    char name[256]={0};
    clGetDeviceInfo(dev, CL_DEVICE_NAME, sizeof name, name, NULL);
    printf("using %s\n", name);
    cl_int err;
    cl_context ctx = clCreateContext(NULL, 1, &dev, NULL, NULL, &err);
    cl_command_queue q = clCreateCommandQueue(ctx, dev, 0, &err);
    const char *src = SRC;
    cl_program prog = clCreateProgramWithSource(ctx, 1, &src, NULL, &err);
    err = clBuildProgram(prog, 1, &dev, "-cl-fast-relaxed-math", NULL, NULL);
    if (err) {
        char log[8192];
        clGetProgramBuildInfo(prog, dev, CL_PROGRAM_BUILD_LOG, sizeof log, log, NULL);
        printf("build err %d\n%s\n", err, log);
        return 1;
    }
    cl_kernel k = clCreateKernel(prog, "sha256_chunks", &err);

    size_t total = 20ull * 1024 * 1024;
    int nchunks = 1024;
    size_t chunk = total / nchunks; /* 20KB */
    size_t nblocks = chunk / 64;
    printf("nchunks %d chunk %zu nblocks %zu\n", nchunks, chunk, nblocks);
    unsigned char *data = malloc(total);
    memset(data, 0x5a, total);
    unsigned char *out = malloc(nchunks * 32);

    cl_mem bd = clCreateBuffer(ctx, CL_MEM_READ_ONLY | CL_MEM_COPY_HOST_PTR, total, data, &err);
    cl_mem bo = clCreateBuffer(ctx, CL_MEM_WRITE_ONLY, nchunks*32, NULL, &err);
    cl_uint nb = (cl_uint)nblocks;
    clSetKernelArg(k, 0, sizeof(bd), &bd);
    clSetKernelArg(k, 1, sizeof(bo), &bo);
    clSetKernelArg(k, 2, sizeof(nb), &nb);
    size_t g = nchunks;
    /* warmup */
    clEnqueueNDRangeKernel(q, k, 1, NULL, &g, NULL, 0, NULL, NULL);
    clFinish(q);
    int reps = 5;
    double t0 = now_s();
    for (int r = 0; r < reps; r++) {
        clEnqueueNDRangeKernel(q, k, 1, NULL, &g, NULL, 0, NULL, NULL);
        clFinish(q);
    }
    double t1 = now_s();
    printf("gpu kernel %.2f ms  %.1f MB/s\n", (t1-t0)/reps*1000, (reps*(double)total/1e6)/(t1-t0));

    clEnqueueReadBuffer(q, bo, CL_TRUE, 0, 32, out, 0, NULL, NULL);
    /* CPU CC of first chunk for rough sanity (no padding, so won't match CC). just print. */
    printf("out0 "); for (int i=0;i<8;i++) printf("%02x", out[i]); printf("\n");

    /* transfer cost */
    t0 = now_s();
    for (int r = 0; r < reps; r++) {
        clEnqueueWriteBuffer(q, bd, CL_FALSE, 0, total, data, 0, NULL, NULL);
        clFinish(q);
    }
    t1 = now_s();
    printf("write %.2f ms\n", (t1-t0)/reps*1000);
    return 0;
}
EOF
SDK=/Library/Developer/CommandLineTools/SDKs/MacOSX.sdk
clang -O2 -isysroot "$SDK" -framework OpenCL -o clsha clsha.c && ./clsha AMD && echo "==== INTEL ====" && ./clsha Intel && echo "==== UHD ====" && ./clsha UHD"}
